//! 🪵️ Complete timber members, actions and connections borrowed before typed ownership.
use crate::sqlite::snapshot::*;
use semio_framework_dsl_record::RecordValue as R;
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use semio_s_artifact_norm_contract::sqlite_native as n;
use semio_s_artifact_norm_contract::sqlite_native::Column::*;
fn count(root:&R)->Result<usize,ValueError>{let mut rows=1;for(id,actions)in[(1,27),(2,18)]{let owners=n::list(n::field(root,id)?)?;rows=n::add(rows,owners.len())?;for owner in owners{rows=n::add(rows,n::list(n::field(n::record(owner)?,actions)?)?.len())?}}for owner in n::list(n::field(root,4)?)?{rows=n::add(rows,1)?;let o=n::record(owner)?;rows=n::add(rows,n::list(n::field(o,4)?)?.len())?;rows=n::add(rows,n::list(n::field(o,5)?)?.len())?}rows=n::add(rows,n::list(n::field(root,5)?)?.len())?;rows=n::add(rows,n::list(n::field(root,6)?)?.len())?;rows=n::add(rows,n::list(n::field(root,7)?)?.len())?;for(id,children)in[(8,12),(9,2)]{let owners=n::list(n::field(root,id)?)?;rows=n::add(rows,owners.len())?;for owner in owners{rows=n::add(rows,n::list(n::field(n::record(owner)?,children)?)?.len())?}}rows=n::add(rows,n::list(n::field(root,10)?)?.len())?;rows=n::add(rows,n::list(n::field(root,11)?)?.len())?;rows=n::add(rows,n::list(n::field(root,12)?)?.len())?;rows=n::add(rows,n::list(n::field(root,13)?)?.len())?;rows=n::add(rows,n::list(n::field(root,14)?)?.len())?;Ok(rows)}
fn write(root:&R,out:&mut RowWriter<'_,'_>)->Result<(),ValueError>{
 out.insert_key("en1995_document",1,&n::cells(root,[Enumeration(0,&["En","De"]),Text(3),Enumeration(15,&["RC1","RC2","RC3"])])?)?;
 for(index,m)in n::list(n::field(root,1)?)?.iter().enumerate(){let m=n::record(m)?;let parent=n::entity(out,"en1995_member",1,index,&n::cells(m,[Text(0),Text(1),Text(2),Enumeration(3,&["beam","column","floor","bridge"]),Text(4),Unsigned(5,u8::MAX as u64),Enumeration(6,&["simplySupported","cantilever","continuousTwoSpan"]),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Real(15),Real(16),Real(17),Real(18),Real(19),Real(20),Real(21),Real(22),Real(23),Real(24),Real(25),Real(26)])?,MEMBER_FLOATS)?;
 for(index,a)in n::list(n::field(m,27)?)?.iter().enumerate(){n::entity(out,"en1995_member_action",parent,index,&n::cells(n::record(a)?,[Text(0),Text(1),Text(2),Text(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10)])?,MEMBER_ACTION_FLOATS)?;}}
 for(index,c)in n::list(n::field(root,2)?)?.iter().enumerate(){let c=n::record(c)?;let parent=n::entity(out,"en1995_connection",1,index,&n::cells(c,[Text(0),Text(1),Text(2),Text(3),Text(4),Unsigned(5,u8::MAX as u64),Real(6),Unsigned(7,u32::MAX as u64),Unsigned(8,u32::MAX as u64),Real(9),Real(10),Real(11),Real(12),Real(13),Boolean(14),Real(15),Unsigned(16,u32::MAX as u64),Real(17)])?,CONNECTION_FLOATS)?;
 for(index,a)in n::list(n::field(c,18)?)?.iter().enumerate(){n::entity(out,"en1995_connection_action",parent,index,&n::cells(n::record(a)?,[Text(0),Text(1),Text(2),Real(3)])?,CONNECTION_ACTION_FLOATS)?;}}
 for(index,c)in n::list(n::field(root,4)?)?.iter().enumerate(){let c=n::record(c)?;let parent=n::entity(out,"en1995_case",1,index,&n::cells(c,[Text(0),Text(1),Text(2),Text(3)])?,&[])?;
 for(index,r)in n::list(n::field(c,4)?)?.iter().enumerate(){n::entity(out,"en1995_case_number",parent,index,&n::cells(n::record(r)?,[Text(0),Real(1)])?,CASE_NUMBER_FLOATS)?;}
 for(index,r)in n::list(n::field(c,5)?)?.iter().enumerate(){n::entity(out,"en1995_case_text",parent,index,&n::cells(n::record(r)?,[Text(0),Text(1)])?,&[])?;}}
 for(index,p)in n::list(n::field(root,5)?)?.iter().enumerate(){n::entity(out,"en1995_placement",1,index,&n::cells(n::record(p)?,[Text(0),Real(1),Real(2),Real(3),Real(4)])?,PLACEMENT_FLOATS)?;}
 for(index,p)in n::list(n::field(root,6)?)?.iter().enumerate(){n::entity(out,"en1995_taper",1,index,&n::cells(n::record(p)?,[Text(0),Text(1),Enumeration(2,&["single-tapered","double-tapered","curved","pitched-cambered"]),Real(3),Real(4),Real(5),Real(6),Real(7),Enumeration(8,&["tension","compression"]),Unsigned(9,u32::MAX as u64),Real(10)])?,TAPER_FLOATS)?;}
 for(index,p)in n::list(n::field(root,7)?)?.iter().enumerate(){n::entity(out,"en1995_cutout",1,index,&n::cells(n::record(p)?,[Text(0),Text(1),Enumeration(2,&["notch","hole"]),Enumeration(3,&["bottom","top"]),Real(4),Real(5),Real(6),Real(7),Real(8),Unsigned(9,u32::MAX as u64),Real(10)])?,CUTOUT_FLOATS)?;}
 for(index,p)in n::list(n::field(root,8)?)?.iter().enumerate(){let parent=n::entity(out,"en1995_fastener",1,index,&n::cells(n::record(p)?,[Text(0),Text(1),Text(2),Unsigned(3,u32::MAX as u64),Unsigned(4,u32::MAX as u64),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11)])?,FASTENER_FLOATS)?;
 for(index,q)in n::list(n::field(n::record(p)?,12)?)?.iter().enumerate(){n::entity(out,"en1995_fastener_position",parent,index,&n::cells(n::record(q)?,[Text(0),Real(1),Real(2)])?,FASTENER_POSITION_FLOATS)?;}}
 for(index,p)in n::list(n::field(root,9)?)?.iter().enumerate(){let parent=n::entity(out,"en1995_panel",1,index,&n::cells(n::record(p)?,[Text(0),Text(1),Real(3),Real(4),Real(5),Real(6)])?,PANEL_FLOATS)?;
 for(index,q)in n::list(n::field(n::record(p)?,2)?)?.iter().enumerate(){n::entity(out,"en1995_panel_layer",parent,index,&n::cells(n::record(q)?,[Text(0),Real(1),Enumeration(2,&["longitudinal","transverse"]),Text(3)])?,PANEL_LAYER_FLOATS)?;}}
 for(index,p)in n::list(n::field(root,10)?)?.iter().enumerate(){n::entity(out,"en1995_floor",1,index,&n::cells(n::record(p)?,[Text(0),Text(1),Real(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11)])?,FLOOR_FLOATS)?;}
 for(index,p)in n::list(n::field(root,11)?)?.iter().enumerate(){n::entity(out,"en1995_diaphragm",1,index,&n::cells(n::record(p)?,[Text(0),Enumeration(1,&["wall","floor","roof"]),Enumeration(2,&["method-a","method-b"]),Real(3),Real(4),Real(5),Unsigned(6,u32::MAX as u64),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12)])?,DIAPHRAGM_FLOATS)?;}
 for(index,p)in n::list(n::field(root,12)?)?.iter().enumerate(){n::entity(out,"en1995_truss",1,index,&n::cells(n::record(p)?,[Text(0),Enumeration(1,&["warren","pratt","howe","king-post"]),Enumeration(2,&["solid","engineered"]),Real(3),Real(4),Unsigned(5,u32::MAX as u64),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12)])?,TRUSS_FLOATS)?;}
 for(index,p)in n::list(n::field(root,13)?)?.iter().enumerate(){n::entity(out,"en1995_bracing",1,index,&n::cells(n::record(p)?,[Text(0),Enumeration(1,&["plan-bracing","bridging","elastic-restraint"]),Text(2),Unsigned(3,u32::MAX as u64),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10)])?,BRACING_FLOATS)?;}
 for(index,p)in n::list(n::field(root,14)?)?.iter().enumerate(){n::entity(out,"en1995_deck",1,index,&n::cells(n::record(p)?,[Text(0),Enumeration(1,&["solid","glulam"]),Enumeration(2,&["threaded-bar","smooth-bar"]),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Real(15),Real(16),Real(17),Real(18)])?,DECK_FLOATS)?;}
 Ok(())
}
/// 🛂️ Exact twenty-table physical rows and IEEE cell words under copied caller controls.
pub fn admit(root:&R,native:&mut NativeDecodeControl<'_>,limits:store::sqlite_snapshot::SqliteDatabaseLimits)->Result<(),ValueError>{n::admit(root,native,limits,En1995Snapshot::SQLITE_SCHEMA,20,70,count(root)?,write)}
